/** Additive M80 restore-normalization successor. Importing performs no I/O. */
import { readFile } from "node:fs/promises"
import type { WorkspaceSql } from "../packages/neuvetra-database/src/workspace"
import {
  EXPECTED_NEW_TABLES,
  MIGRATION_NAME,
  MIGRATION_SHA256,
  assertExactRestore,
  assertSchema22Delta,
  captureApplicationState,
  hash,
  sha,
  type ApplicationState,
} from "./m80-backup-core"
import { canonical, check, sameExactInventory } from "../tools/staging/m78-inventory"

export const M80_BACKUP_V2_NORMALIZATION_PROFILE = "neuvetra.m80.foundation-restore-normalization-proof.v2" as const
export const M80_BACKUP_V2_PRESERVATION_PROFILE = "neuvetra.m80.foundation-hosted-preservation-receipt.v2" as const

type DefaultAcl = ApplicationState["inventory"]["defaultAcls"][number]
type InternalTrigger = ApplicationState["internalTriggers"][number]

const ordinal = (left: unknown, right: unknown): number => {
  const a = canonical(left), b = canonical(right)
  return a < b ? -1 : a > b ? 1 : 0
}

function assertDefaultAclRow(value: unknown): asserts value is DefaultAcl {
  check(!!value && typeof value === "object" && !Array.isArray(value) && Object.getPrototypeOf(value) === Object.prototype, "M80_V2_DEFAULT_ACL_ROW_MALFORMED")
  const row = value as Record<string, unknown>
  check(Object.keys(row).sort().join("|") === "acl|kind|owner|schema", "M80_V2_DEFAULT_ACL_ROW_MALFORMED")
  const identifier = (item: unknown) => typeof item === "string" && Buffer.byteLength(item, "utf8") >= 1 && Buffer.byteLength(item, "utf8") <= 63 && !item.includes("\0")
  check(identifier(row.owner) && identifier(row.schema) && typeof row.kind === "string" && /^[rSfTn]$/.test(row.kind) && typeof row.acl === "string" && row.acl.length > 0 && !row.acl.includes("\0"), "M80_V2_DEFAULT_ACL_ROW_MALFORMED")
}

function assertDefaultAclRows(rows: DefaultAcl[]): void {
  check(Array.isArray(rows), "M80_V2_DEFAULT_ACL_ROW_MALFORMED")
  rows.forEach(assertDefaultAclRow)
}

export interface M80BackupV2NormalizationProof {
  profile: typeof M80_BACKUP_V2_NORMALIZATION_PROFILE
  sourceRawApplicationStateSha256: string
  restoredRawApplicationStateSha256: string
  sourceRawMetadataSha256: string
  restoredRawMetadataSha256: string
  sourceExternalDefaultAclRowsExcluded: number
  restoredExternalDefaultAclRows: 0
  scopedDefaultAclRowsExact: true
  sourceInternalTriggerRows: number
  restoredInternalTriggerRows: number
  internalTriggerSemanticMultisetExact: true
  allOtherInventoryMetadataExact: true
  sourceNormalizedMetadataSha256: string
  restoredNormalizedMetadataSha256: string
  normalizedMetadataExact: true
}

export interface M80BackupV2NormalizationReceipt extends M80BackupV2NormalizationProof {
  completedAt: string
  disposableDatabaseName: string
  sourceBackupReceiptSha256: string
  sourceContentSha256: string
  restoredContentSha256: string
}

export interface M80BackupV2PreservationReceipt {
  profile: typeof M80_BACKUP_V2_PRESERVATION_PROFILE
  completedAt: string
  disposableDatabaseName: string
  sourceBackupReceiptSha256: string
  normalizationProof: { path: string; sha256: string }
  sourceContentSha256: string
  restoredContentSha256: string
  sourceRawApplicationStateSha256: string
  restoredRawApplicationStateSha256: string
  sourceNormalizedMetadataSha256: string
  restoredNormalizedMetadataSha256: string
  oldContentExact: true
  applicationMetadataEquivalent: true
  rawMetadataHashesEqual: boolean
}

function scopedDefaultAcls(rows: DefaultAcl[]): DefaultAcl[] {
  assertDefaultAclRows(rows)
  return rows
    .filter(row => row.schema === "neuvetra" || row.schema === "*")
    .map(row => structuredClone(row))
    .sort(ordinal)
}

function externalDefaultAcls(rows: DefaultAcl[]): DefaultAcl[] {
  assertDefaultAclRows(rows)
  return rows.filter(row => row.schema !== "neuvetra" && row.schema !== "*")
}

function normalizedInternalTriggers(rows: InternalTrigger[]): InternalTrigger[] {
  return rows.map(row => structuredClone(row)).sort(ordinal)
}

function normalizedMetadataProjection(state: ApplicationState) {
  const value = state.inventory
  return {
    nonReceiptTables: state.observedNonReceiptTables,
    tableSecurity: state.tableSecurity,
    schemaSecurity: state.schemaSecurity,
    internalTriggers: normalizedInternalTriggers(state.internalTriggers),
    functions: value.functions,
    tableObjects: value.tableObjects,
    sequences: value.sequences,
    roles: value.roles,
    memberships: value.memberships,
    defaultAcls: scopedDefaultAcls(value.defaultAcls),
    dependencies: value.dependencies,
  }
}

function rawContentProjection(state: ApplicationState) {
  return {
    tables: state.inventory.tables.filter(table => table.name !== "schema_migrations").map(table => ({ name: table.name, count: table.count, rowHashes: table.rowHashes })),
    migrationReceipts: state.migrationReceipts,
  }
}

function rawMetadataProjection(state: ApplicationState) {
  const value = state.inventory
  return {
    nonReceiptTables: state.observedNonReceiptTables,
    tableSecurity: state.tableSecurity,
    schemaSecurity: state.schemaSecurity,
    internalTriggers: state.internalTriggers,
    functions: value.functions,
    tableObjects: value.tableObjects,
    sequences: value.sequences,
    roles: value.roles,
    memberships: value.memberships,
    defaultAcls: value.defaultAcls,
    dependencies: value.dependencies,
  }
}

function assertRawStateBinding(state: ApplicationState): void {
  check(state.contentSha256 === hash(rawContentProjection(state)), "M80_V2_RAW_CONTENT_HASH_CHANGED")
  check(state.metadataSha256 === hash(rawMetadataProjection(state)), "M80_V2_RAW_METADATA_HASH_CHANGED")
  check(state.applicationStateSha256 === hash({ contentSha256: state.contentSha256, metadataSha256: state.metadataSha256 }), "M80_V2_RAW_APPLICATION_STATE_HASH_CHANGED")
}

export function m80BackupV2NormalizedMetadataSha256(state: ApplicationState): string {
  return hash(normalizedMetadataProjection(state))
}

export function normalizeM80BackupV2State(state: ApplicationState): ApplicationState {
  const inventory = { ...structuredClone(state.inventory), defaultAcls: scopedDefaultAcls(state.inventory.defaultAcls) }
  const internalTriggers = normalizedInternalTriggers(state.internalTriggers)
  const normalized = { ...structuredClone(state), inventory, internalTriggers }
  const metadataSha256 = m80BackupV2NormalizedMetadataSha256(normalized)
  return { ...normalized, metadataSha256, applicationStateSha256: hash({ contentSha256: normalized.contentSha256, metadataSha256 }) }
}

function assertDefaultAclDifference(source: ApplicationState, restored: ApplicationState): number {
  const sourceScoped = scopedDefaultAcls(source.inventory.defaultAcls), restoredScoped = scopedDefaultAcls(restored.inventory.defaultAcls)
  check(hash(sourceScoped) === hash(restoredScoped), "M80_V2_SCOPED_DEFAULT_ACL_CHANGED")
  check(externalDefaultAcls(restored.inventory.defaultAcls).length === 0, "M80_V2_RESTORED_EXTERNAL_DEFAULT_ACL_UNEXPECTED")
  return externalDefaultAcls(source.inventory.defaultAcls).length
}

function assertTriggerMultiset(source: ApplicationState, restored: ApplicationState): void {
  const before = normalizedInternalTriggers(source.internalTriggers), after = normalizedInternalTriggers(restored.internalTriggers)
  check(before.length === after.length && hash(before) === hash(after), "M80_V2_INTERNAL_TRIGGER_MULTISET_CHANGED")
}

function assertOtherExact(source: ApplicationState, restored: ApplicationState): void {
  const sourceInventory = { ...structuredClone(source.inventory), defaultAcls: [] }
  const restoredInventory = { ...structuredClone(restored.inventory), defaultAcls: [] }
  sameExactInventory(sourceInventory, restoredInventory)
  check(hash(source.migrationReceipts) === hash(restored.migrationReceipts), "M80_V2_MIGRATION_RECEIPTS_CHANGED")
  check(hash(source.observedNonReceiptTables) === hash(restored.observedNonReceiptTables), "M80_V2_TABLE_SET_CHANGED")
  check(hash(source.tableSecurity) === hash(restored.tableSecurity), "M80_V2_TABLE_SECURITY_CHANGED")
  check(hash(source.schemaSecurity) === hash(restored.schemaSecurity), "M80_V2_SCHEMA_SECURITY_CHANGED")
  check(source.contentSha256 === restored.contentSha256, "M80_V2_CONTENT_CHANGED")
}

export function assertM80BackupV2ExactRestore(source: ApplicationState, restored: ApplicationState): M80BackupV2NormalizationProof {
  assertRawStateBinding(source)
  assertRawStateBinding(restored)
  const excluded = assertDefaultAclDifference(source, restored)
  assertTriggerMultiset(source, restored)
  assertOtherExact(source, restored)
  const before = normalizeM80BackupV2State(source), after = normalizeM80BackupV2State(restored)
  assertExactRestore(before, after)
  return {
    profile: M80_BACKUP_V2_NORMALIZATION_PROFILE,
    sourceRawApplicationStateSha256: source.applicationStateSha256,
    restoredRawApplicationStateSha256: restored.applicationStateSha256,
    sourceRawMetadataSha256: source.metadataSha256,
    restoredRawMetadataSha256: restored.metadataSha256,
    sourceExternalDefaultAclRowsExcluded: excluded,
    restoredExternalDefaultAclRows: 0,
    scopedDefaultAclRowsExact: true,
    sourceInternalTriggerRows: source.internalTriggers.length,
    restoredInternalTriggerRows: restored.internalTriggers.length,
    internalTriggerSemanticMultisetExact: true,
    allOtherInventoryMetadataExact: true,
    sourceNormalizedMetadataSha256: before.metadataSha256,
    restoredNormalizedMetadataSha256: after.metadataSha256,
    normalizedMetadataExact: true,
  }
}

function subtractTriggerMultiset(source: InternalTrigger[], after: InternalTrigger[]): InternalTrigger[] {
  const remaining = new Map<string, { row: InternalTrigger; count: number }>()
  for (const row of normalizedInternalTriggers(after)) {
    const key = canonical(row), item = remaining.get(key)
    remaining.set(key, { row, count: (item?.count ?? 0) + 1 })
  }
  for (const row of normalizedInternalTriggers(source)) {
    const key = canonical(row), item = remaining.get(key)
    check(!!item && item.count > 0, "M80_V2_OLD_INTERNAL_TRIGGER_MISSING")
    if (item.count === 1) remaining.delete(key)
    else item.count--
  }
  return [...remaining.values()].flatMap(item => Array.from({ length: item.count }, () => item.row))
}

export function assertM80BackupV2RawTriggerDelta(restoredBaseline: ApplicationState, after: ApplicationState): void {
  const addedTriggers = subtractTriggerMultiset(restoredBaseline.internalTriggers, after.internalTriggers)
  check(addedTriggers.every(row => (EXPECTED_NEW_TABLES as readonly string[]).includes(row.constraintTable.replace("neuvetra.", ""))), "M80_V2_UNEXPECTED_INTERNAL_TRIGGER_ADDED")
}

export async function assertM80BackupV2RawSchema22Delta(restoredBaseline: ApplicationState, after: ApplicationState, tx: WorkspaceSql): Promise<void> {
  check(hash(restoredBaseline.inventory.defaultAcls) === hash(after.inventory.defaultAcls), "M80_V2_SCHEMA22_DEFAULT_ACL_CHANGED")
  assertM80BackupV2RawTriggerDelta(restoredBaseline, after)
  await assertSchema22Delta(restoredBaseline, after, tx)
}

export async function applyM80BackupV2Schema22(tx: WorkspaceSql, restoredBaseline: ApplicationState): Promise<ApplicationState> {
  const current = await captureApplicationState(tx)
  assertExactRestore(restoredBaseline, current)
  const sql = await readFile(`packages/neuvetra-database/src/migrations/${MIGRATION_NAME}`, "utf8")
  check(sha(sql) === MIGRATION_SHA256, "M80_V2_MIGRATION_BYTES_CHANGED")
  await tx.exec(sql)
  await tx.query("insert into neuvetra.schema_migrations(name,sha256) values($1,$2)", [MIGRATION_NAME, MIGRATION_SHA256])
  const after = await captureApplicationState(tx)
  await assertM80BackupV2RawSchema22Delta(restoredBaseline, after, tx)
  return after
}

import { afterAll, beforeAll, describe, expect, test } from "bun:test"
import { createPostgresConnection } from "../packages/neuvetra-database/src/hosted"
import { captureApplicationState, hash, type ApplicationState } from "./m80-backup-core"
import { assertM80BackupV2ExactRestore, assertM80BackupV2RawTriggerDelta } from "./m80-backup-v2-core"
import { assertM80BackupV2PermissionDenied, assertM80BackupV2RuntimePrivileges } from "./m80-backup-v2-rehearsal"
import { EXPECTED_NEW_SEQUENCES, EXPECTED_NEW_TABLES } from "./m80-backup-core"

let database: ReturnType<typeof createPostgresConnection>
let baseline: ApplicationState

const copy = (): ApplicationState => structuredClone(baseline)

const bind = (state: ApplicationState): ApplicationState => {
  const contentSha256 = hash({ tables: state.inventory.tables.filter(table => table.name !== "schema_migrations").map(table => ({ name: table.name, count: table.count, rowHashes: table.rowHashes })), migrationReceipts: state.migrationReceipts })
  const value = state.inventory
  const metadataSha256 = hash({ nonReceiptTables: state.observedNonReceiptTables, tableSecurity: state.tableSecurity, schemaSecurity: state.schemaSecurity, internalTriggers: state.internalTriggers, functions: value.functions, tableObjects: value.tableObjects, sequences: value.sequences, roles: value.roles, memberships: value.memberships, defaultAcls: value.defaultAcls, dependencies: value.dependencies })
  return Object.assign(state, { contentSha256, metadataSha256, applicationStateSha256: hash({ contentSha256, metadataSha256 }) })
}

beforeAll(async () => {
  database = createPostgresConnection("postgres://supabase_admin@127.0.0.1:55472/m78_ops_continuation_20260922", { tls: false, maxConnections: 1 })
  baseline = await database.transaction(async tx => {
    await tx.exec("set transaction isolation level repeatable read read only")
    return captureApplicationState(tx)
  })
})

afterAll(async () => database.close())

describe("M80 restore normalization v2", () => {
  test("requires exact SELECT-only table grants, no sequence grants and SQLSTATE 42501", () => {
    const tablePrivileges = EXPECTED_NEW_TABLES.flatMap(name => ["SELECT", "INSERT", "UPDATE", "DELETE", "TRUNCATE", "REFERENCES", "TRIGGER"].map(privilege => ({ name, privilege, allowed: privilege === "SELECT" })))
    const sequencePrivileges = EXPECTED_NEW_SEQUENCES.flatMap(name => ["SELECT", "USAGE", "UPDATE"].map(privilege => ({ name, privilege, allowed: false })))
    expect(() => assertM80BackupV2RuntimePrivileges(tablePrivileges, sequencePrivileges)).not.toThrow()
    for (const mutate of [
      () => { tablePrivileges[0]!.allowed = false },
      () => { tablePrivileges.find(row => row.privilege === "DELETE")!.allowed = true },
      () => { sequencePrivileges[0]!.allowed = true },
      () => { tablePrivileges.pop() },
    ]) {
      const tables = structuredClone(tablePrivileges), sequences = structuredClone(sequencePrivileges); mutate()
      expect(() => assertM80BackupV2RuntimePrivileges(tablePrivileges, sequencePrivileges)).toThrow()
      tablePrivileges.splice(0, tablePrivileges.length, ...tables); sequencePrivileges.splice(0, sequencePrivileges.length, ...sequences)
    }
    expect(() => assertM80BackupV2PermissionDenied({ code: "42501" })).not.toThrow()
    for (const error of [{ code: "23503" }, { code: "ECONNRESET" }, new Error("closed"), null]) expect(() => assertM80BackupV2PermissionDenied(error)).toThrow("M80_V2_RUNTIME_WRITE_DENIAL_NOT_PROVEN")
  })

  test("accepts only external-schema ACL omission and trigger permutation", () => {
    const source = copy(), restored = copy()
    source.inventory.defaultAcls.push({ owner: "postgres", schema: "provider_private", kind: "r", acl: "{postgres=arwdDxt/postgres}" })
    restored.internalTriggers.reverse()
    bind(source); bind(restored)
    const proof = assertM80BackupV2ExactRestore(source, restored)
    expect(proof.sourceExternalDefaultAclRowsExcluded).toBe(1)
    expect(proof.internalTriggerSemanticMultisetExact).toBe(true)
    expect(proof.sourceNormalizedMetadataSha256).toBe(proof.restoredNormalizedMetadataSha256)
  })

  test.each(["*", "neuvetra"])("refuses a changed %s default ACL", schema => {
    const source = copy(), restored = copy()
    source.inventory.defaultAcls.push({ owner: "postgres", schema, kind: "r", acl: "{postgres=arwdDxt/postgres}" })
    bind(source)
    expect(() => assertM80BackupV2ExactRestore(source, restored)).toThrow("M80_V2_SCOPED_DEFAULT_ACL_CHANGED")
  })

  test("refuses an unexpected external default ACL on the restored database", () => {
    const source = copy(), restored = copy()
    restored.inventory.defaultAcls.push({ owner: "postgres", schema: "provider_private", kind: "r", acl: "{postgres=arwdDxt/postgres}" })
    bind(restored)
    expect(() => assertM80BackupV2ExactRestore(source, restored)).toThrow("M80_V2_RESTORED_EXTERNAL_DEFAULT_ACL_UNEXPECTED")
  })

  test("retains star defaults conservatively and refuses malformed ACL rows", () => {
    const star = copy(), restored = copy()
    star.inventory.defaultAcls.push({ owner: "postgres", schema: "*", kind: "r", acl: "{postgres=arwdDxt/postgres}" })
    bind(star)
    expect(() => assertM80BackupV2ExactRestore(star, restored)).toThrow("M80_V2_SCOPED_DEFAULT_ACL_CHANGED")
    for (const schema of [null, "", "bad\0schema", "x".repeat(64)]) {
      const malformed = copy()
      malformed.inventory.defaultAcls.push({ owner: "postgres", schema, kind: "r", acl: "{postgres=arwdDxt/postgres}" } as never)
      bind(malformed)
      expect(() => assertM80BackupV2ExactRestore(malformed, restored)).toThrow("M80_V2_DEFAULT_ACL_ROW_MALFORMED")
    }
    const extraKey = copy()
    extraKey.inventory.defaultAcls.push({ owner: "postgres", schema: "external", kind: "r", acl: "{postgres=arwdDxt/postgres}", extra: true } as never)
    bind(extraKey)
    expect(() => assertM80BackupV2ExactRestore(extraKey, restored)).toThrow("M80_V2_DEFAULT_ACL_ROW_MALFORMED")
  })

  test("refuses omitted, changed, extra and duplicate trigger semantics", () => {
    const omitted = copy(); omitted.internalTriggers.pop(); bind(omitted)
    expect(() => assertM80BackupV2ExactRestore(baseline, omitted)).toThrow("M80_V2_INTERNAL_TRIGGER_MULTISET_CHANGED")
    const changed = copy(); changed.internalTriggers[0] = { ...changed.internalTriggers[0]!, constraintName: `${changed.internalTriggers[0]!.constraintName}_changed` }; bind(changed)
    expect(() => assertM80BackupV2ExactRestore(baseline, changed)).toThrow("M80_V2_INTERNAL_TRIGGER_MULTISET_CHANGED")
    const extra = copy(); extra.internalTriggers.push({ ...extra.internalTriggers[0]!, constraintName: "unexpected_constraint" }); bind(extra)
    expect(() => assertM80BackupV2ExactRestore(baseline, extra)).toThrow("M80_V2_INTERNAL_TRIGGER_MULTISET_CHANGED")
    const duplicate = copy(); duplicate.internalTriggers.push(structuredClone(duplicate.internalTriggers[0]!)); bind(duplicate)
    expect(() => assertM80BackupV2ExactRestore(baseline, duplicate)).toThrow("M80_V2_INTERNAL_TRIGGER_MULTISET_CHANGED")
  })

  test("preserves every duplicate old-trigger occurrence across migration", () => {
    const counts = new Map<string, number>()
    for (const row of baseline.internalTriggers) counts.set(JSON.stringify(row), (counts.get(JSON.stringify(row)) ?? 0) + 1)
    const duplicateKey = [...counts].find(([, count]) => count > 1)?.[0]
    expect(duplicateKey).toBeTruthy()
    const missing = copy(), index = missing.internalTriggers.findIndex(row => JSON.stringify(row) === duplicateKey)
    missing.internalTriggers.splice(index, 1)
    expect(() => assertM80BackupV2RawTriggerDelta(baseline, missing)).toThrow("M80_V2_OLD_INTERNAL_TRIGGER_MISSING")
    const extraOld = copy(); extraOld.internalTriggers.push(structuredClone(extraOld.internalTriggers[0]!))
    expect(() => assertM80BackupV2RawTriggerDelta(baseline, extraOld)).toThrow("M80_V2_UNEXPECTED_INTERNAL_TRIGGER_ADDED")
    const expectedNew = copy(); expectedNew.internalTriggers.push({ ...expectedNew.internalTriggers[0]!, tableName: "neuvetra.scope1_beta_requests", constraintTable: "neuvetra.scope1_beta_requests", constraintName: "scope1_beta_requests_company_id_fkey" })
    expect(() => assertM80BackupV2RawTriggerDelta(baseline, expectedNew)).not.toThrow()
  })

  test("refuses other metadata and content changes", () => {
    const security = copy(); security.tableSecurity[0] = { ...security.tableSecurity[0]!, forceRowSecurity: !security.tableSecurity[0]!.forceRowSecurity }; bind(security)
    expect(() => assertM80BackupV2ExactRestore(baseline, security)).toThrow("M80_V2_TABLE_SECURITY_CHANGED")
    const roles = copy(); roles.inventory.roles[0] = { ...roles.inventory.roles[0]!, rolinherit: !roles.inventory.roles[0]!.rolinherit }; bind(roles)
    expect(() => assertM80BackupV2ExactRestore(baseline, roles)).toThrow()
    const dependency = copy(); dependency.inventory.dependencies.push({ schema: "foreign", relation: "unexpected" }); bind(dependency)
    expect(() => assertM80BackupV2ExactRestore(baseline, dependency)).toThrow()
    const content = copy(); content.contentSha256 = "0".repeat(64)
    expect(() => assertM80BackupV2ExactRestore(baseline, content)).toThrow("M80_V2_RAW_CONTENT_HASH_CHANGED")
  })

  test("recomputes every raw state hash before issuing a proof", () => {
    for (const side of ["source", "restored"] as const) for (const field of ["contentSha256", "metadataSha256", "applicationStateSha256"] as const) {
      const source = copy(), restored = copy()
      ;(side === "source" ? source : restored)[field] = "0".repeat(64)
      expect(() => assertM80BackupV2ExactRestore(source, restored)).toThrow(/^M80_V2_RAW_/)
    }
  })
})

