}

type RuntimeTablePrivilegeRow = { name: string; privilege: string; allowed: boolean }
type RuntimeSequencePrivilegeRow = { name: string; privilege: string; allowed: boolean }

const TABLE_PRIVILEGES = ["SELECT", "INSERT", "UPDATE", "DELETE", "TRUNCATE", "REFERENCES", "TRIGGER"] as const
const SEQUENCE_PRIVILEGES = ["SELECT", "USAGE", "UPDATE"] as const

export function assertM80BackupV2RuntimePrivileges(tableRows: RuntimeTablePrivilegeRow[], sequenceRows: RuntimeSequencePrivilegeRow[]): void {
  check(Array.isArray(tableRows) && tableRows.length === EXPECTED_NEW_TABLES.length * TABLE_PRIVILEGES.length, "M80_V2_RUNTIME_TABLE_PRIVILEGES_CHANGED")
  const tableKeys = new Set<string>()
  for (const row of tableRows) {
